  'pkg.eyebrow': 'Apprendre le handpan',
  'pkg.title': 'Trois façons<br/><em>de commencer.</em>',
  'pkg.lede': 'Tout se déroule sur la terrasse en plein air du Noom Studio à Lamai, instruments fournis — ou nous venons à ton hôtel ou ta villa. Écris-nous et on trouvera un créneau.',
  'p1.tag': 'Premier goût',
