  'p2.tag': 'Signature',
  'p2.title': 'Voyage Handpan<br/><em>de 3 jours.</em>',
  'p2.per': '10 heures &middot; trois jours &middot; certificat',
  'p2.desc': 'Le stage complet — des premières notes à ton propre morceau enregistré, avec un handpan pour t’exercer pendant ton séjour et des cours vidéo pour continuer ensuite.',
  'p2.cta': 'Découvrir le Voyage &nbsp;&rarr;',
