  'nav.learn': 'Handpan öğren',
  'nav.sj': 'Ses yolculukları',
  'hero.title2': 'Deniz kenarında<br/><em>handpan öğren.</em>',
  'hero.sub2': 'Lamai’de okyanus manzaralı terasta dersler, kurslar ve üç günlük handpan kursu — müzik geçmişi gerekmez.',
  'hero.cta1': 'Öğrenmeye başla &nbsp;&rarr;',
